  ('dishwashing', 'Dishwashing', array['dish liquid', 'dishwasher']::text[], 2),
  ('hands', 'Hands', array['hand soap']::text[], 3)
on conflict (id) do update set
    name = excluded.name,
    subcategories = excluded.subcategories,
    sort_order = excluded.sort_order;

insert into public.ingredients (id, name, aliases, family, level, dimension, confidence, why) values
  ('sls', 'Sodium lauryl sulfate', array['SLS', 'sodium dodecyl sulfate']::text[], 'sulfates', 'moderate', 'health', 'strong', 'A strong detergent surfactant that cuts grease well and strips skin just as efficiently. Well documented as a skin and eye irritant at the concentrations used in dish liquid.'),
  ('sles', 'Sodium laureth sulfate', array['SLES', 'sodium lauryl ether sulfate']::text[], 'sulfates', 'moderate', 'health', 'moderate', 'Milder on skin than SLS, but made by ethoxylation, which can leave trace 1,4-dioxane behind unless the manufacturer strips it. Purity depends entirely on process disclosure.'),
  ('als', 'Ammonium lauryl sulfate', array['ALS']::text[], 'sulfates', 'moderate', 'health', 'moderate', 'The same irritation profile as other sulfate surfactants, used where a denser, longer-lasting foam is wanted.'),
  ('coco-glucoside', 'Coco-glucoside', array['coco glucoside', 'decyl glucoside']::text[], 'sugar surfactants', 'clear', 'health', 'moderate', 'Sugar surfactant made from coconut and corn, used as the sulfate replacement in most fragrance-free formulas. Readily biodegradable, no meaningful irritation signal.'),
  ('alcohol-ethoxylates', 'Alcohol ethoxylates', array['C12-16 pareth', 'laureth-7']::text[], 'ethoxylates', 'low', 'health', 'moderate', 'Workhorse non-ionic surfactants in all-purpose sprays. Low concern in themselves; as with any ethoxylated ingredient, the open question is residual 1,4-dioxane from manufacturing.'),
  ('npe', 'Nonylphenol ethoxylates', array['NPE', 'nonoxynol']::text[], 'ethoxylates', 'high', 'both', 'strong', 'Break down in water into nonylphenol, which is persistent and hormonally active in fish at very low concentrations. Phased out across the EU and voluntarily abandoned by most US manufacturers — its presence signals an old formula.'),
  ('mit', 'Methylisothiazolinone', array['MIT', 'MI']::text[], 'isothiazolinones', 'high', 'health', 'strong', 'A potent contact allergen. Sensitization rates climbed sharply after it replaced parabens across household and rinse-off products, to the point that dermatology bodies called it an epidemic. Restricted in leave-on products in the EU.'),
  ('bit', 'Benzisothiazolinone', array['BIT']::text[], 'isothiazolinones', 'moderate', 'health', 'moderate', 'The same chemical family as MIT and a recognized contact allergen, though sensitization appears less frequent. Common in laundry liquids and pods.'),
  ('methylparaben', 'Methylparaben', array['methyl paraben']::text[], 'parabens', 'moderate', 'health', 'moderate', 'The shortest-chain paraben and the least hormonally active. An effective preservative; the endocrine signal weakens considerably at this chain length.'),
  ('propylparaben', 'Propylparaben', array['propyl paraben']::text[], 'parabens', 'high', 'health', 'moderate', 'A longer-chain paraben with measurable estrogenic activity in laboratory studies. Restricted in some jurisdictions; the human-exposure picture is still debated.'),
  ('butylparaben', 'Butylparaben', array['butyl paraben']::text[], 'parabens', 'high', 'health', 'moderate', 'The most hormonally active of the common parabens in laboratory assays. Increasingly reformulated out even where it remains legal.'),
  ('dmdm-hydantoin', 'DMDM hydantoin', array['DMDM']::text[], 'formaldehyde releasers', 'high', 'health', 'strong', 'Preserves by slowly releasing formaldehyde, a recognized human carcinogen by inhalation. The releasing mechanism is not in dispute; the exposure level is.'),
  ('quaternium-15', 'Quaternium-15', '{}'::text[], 'formaldehyde releasers', 'high', 'health', 'strong', 'Another formaldehyde-releasing preservative, and among the more common causes of preservative contact allergy.'),
  ('phenoxyethanol', 'Phenoxyethanol', '{}'::text[], 'glycol ethers', 'low', 'health', 'moderate', 'A broad-spectrum preservative capped at 1% in most markets and generally well tolerated at that limit. Worth knowing it is there; rarely worth avoiding.'),
  ('sodium-hypochlorite', 'Sodium hypochlorite', array['chlorine bleach', 'bleach']::text[], 'chlorine bleach', 'moderate', 'health', 'strong', 'Genuinely effective disinfection, and the reason bleach still has a place. Irritating to airways in use, and forms chloramine gas if it meets ammonia — a handling risk rather than a residue risk.'),
  ('benzalkonium-chloride', 'Benzalkonium chloride', array['quats', 'quaternary ammonium compounds', 'ADBAC']::text[], 'quats', 'high', 'both', 'moderate', 'The disinfectant in most "kills 99.9%" sprays. Repeated occupational exposure is linked to asthma, and heavy household use is implicated in bacterial resistance. Persists on surfaces long after the spray has dried.'),
  ('triclosan', 'Triclosan', '{}'::text[], 'antibacterials', 'high', 'both', 'strong', 'Banned from consumer hand soap by the FDA in 2016 after manufacturers failed to show it beat plain soap and water. Persistent in waterways and implicated in resistance. Still turns up in some surface products.'),
  ('hydrogen-peroxide', 'Hydrogen peroxide', '{}'::text[], 'oxygen bleach', 'low', 'health', 'strong', 'Disinfects and whitens, then breaks down into water and oxygen. Irritating at high concentration, unremarkable at household strength.'),
  ('butoxyethanol', '2-Butoxyethanol', array['butyl cellosolve', 'ethylene glycol monobutyl ether']::text[], 'glycol ethers', 'high', 'health', 'strong', 'The solvent that makes heavy-duty degreasers work. Absorbed through skin as well as inhaled, and associated with blood-cell effects at occupational exposures. Ventilation is not optional with this one.'),
  ('ammonia', 'Ammonia', array['ammonium hydroxide']::text[], 'ammonia', 'moderate', 'health', 'strong', 'Cuts grease and dries without streaking, which is why it persists in glass cleaner. A sharp respiratory irritant, and produces toxic chloramine gas if it meets bleach.'),
  ('sodium-hydroxide', 'Sodium hydroxide', array['caustic soda', 'lye']::text[], 'caustics', 'moderate', 'health', 'strong', 'Strongly caustic, and the active in oven and drain products. Causes burns on contact at working strength; used at a fraction of a percent elsewhere as a pH adjuster, where it is unremarkable.'),
  ('ethanol', 'Ethanol', array['alcohol', 'ethyl alcohol']::text[], 'alcohols', 'low', 'health', 'strong', 'Evaporates clean and leaves no film, which is what a glass cleaner needs. Flammable in concentrate; no residue concern.'),
  ('fragrance', 'Fragrance', array['parfum', 'perfume', 'aroma', 'fragrance (parfum)']::text[], 'fragrance', 'high', 'health', 'moderate', 'Not one ingredient — a trade-secret blend that can hold dozens of undisclosed components, including phthalates and known allergens. The concern is the non-disclosure itself: this ingredient cannot be evaluated, only trusted.'),
  ('essential-oils', 'Essential oil blend', array['essential oils', 'botanical extracts']::text[], 'botanical fragrance', 'low', 'health', 'limited', 'Disclosed botanicals, which is a real improvement on a trade-secret blend — you can at least see what is in it. Still fragrance, though, and still capable of triggering a reaction in people who are sensitized.'),
  ('limonene', 'Limonene', array['d-limonene']::text[], 'fragrance allergens', 'moderate', 'health', 'strong', 'The citrus note in most kitchen sprays, and a capable degreaser in its own right. Oxidizes on contact with air into a recognized contact allergen, which is why EU rules require it to be named.'),
  ('linalool', 'Linalool', '{}'::text[], 'fragrance allergens', 'moderate', 'health', 'strong', 'A floral note with the same oxidation-to-allergen behavior as limonene, and declared under the same EU rules.'),
  ('phosphates', 'Phosphates', array['sodium tripolyphosphate', 'STPP']::text[], 'phosphates', 'moderate', 'environment', 'strong', 'Excellent water softeners with no meaningful health concern, and a serious downstream one: they drive algal blooms and oxygen collapse in freshwater. Restricted in laundry and dish detergents across many states and markets.'),
  ('edta', 'EDTA', array['tetrasodium EDTA', 'disodium EDTA']::text[], 'chelators', 'moderate', 'environment', 'moderate', 'Binds hard-water minerals so surfactants can work. Biodegrades poorly and can remobilize heavy metals already settled in sediment. Citrate and gluconate do the same job and break down.'),
  ('optical-brighteners', 'Optical brighteners', array['fluorescent whitening agents', 'stilbene']::text[], 'optical brighteners', 'moderate', 'both', 'moderate', 'Do not clean anything. They deposit on fabric and fluoresce under daylight so whites read whiter, then persist in waterways. A cosmetic additive sold as cleaning performance.'),
  ('enzymes', 'Enzymes', array['protease', 'amylase', 'lipase', 'subtilisin']::text[], 'enzymes', 'low', 'health', 'moderate', 'Digest protein, starch and grease stains at low temperatures, which is how a cold wash gets clean. Respiratory sensitizers as an airborne dust in manufacturing; encapsulated in finished liquids, the risk is small.'),
  ('pfas', 'PFAS', array['PTFE', 'perfluorinated compounds', 'fluorosurfactants']::text[], 'pfas', 'high', 'both', 'strong', 'Used for water- and stain-repellency. They do not meaningfully break down, and accumulate in blood and drinking water. The persistence is beyond dispute.'),
  ('palm-oil', 'Palm-derived surfactants', array['elaeis guineensis', 'palm kernel oil', 'sodium palmate']::text[], 'palm derivatives', 'moderate', 'environment', 'strong', 'No health concern at all. The issue is upstream: uncertified palm is a leading driver of tropical deforestation. RSPO certification changes this assessment materially.'),
  ('citric-acid', 'Citric acid', '{}'::text[], 'acids', 'clear', 'health', 'strong', 'Dissolves limescale and soap scum, adjusts pH, and biodegrades completely. No concern.'),
  ('sodium-bicarbonate', 'Sodium bicarbonate', array['baking soda']::text[], 'mineral salts', 'clear', 'health', 'strong', 'A mild alkaline abrasive and deodorizer. No concern at use concentrations.'),
  ('sodium-carbonate', 'Sodium carbonate', array['washing soda', 'soda ash']::text[], 'mineral salts', 'clear', 'health', 'strong', 'Softens water and lifts grease in laundry and dishwasher formulas. Alkaline enough to warrant gloves in concentrate, unremarkable in use.'),
  ('glycerin', 'Glycerin', array['glycerol', 'vegetable glycerin']::text[], 'humectants', 'clear', 'health', 'strong', 'Keeps hand soap from drying skin and stops a formula separating. No concern; sourcing — palm or vegetable — is the only open question.')
