insert into public.certifications (id, name, body, rigor, covers, what) values
  ('safer-choice', 'EPA Safer Choice', 'US Environmental Protection Agency', 'third-party', 'ingredients', 'Every ingredient reviewed by EPA scientists against safer-chemistry criteria, with full disclosure required. The most relevant mark there is for household cleaning.'),
  ('green-seal', 'Green Seal', 'Green Seal, Inc.', 'third-party', 'ingredients and performance', 'Sets limits on toxicity and VOCs, and — unusually — requires the product to prove it actually cleans before it can carry the mark.'),
  ('ewg-verified', 'EWG Verified', 'Environmental Working Group', 'third-party', 'ingredients', 'Full ingredient disclosure required, including what is inside any fragrance, and nothing on EWG’s restricted list. Reviewed annually.'),
  ('made-safe', 'MADE SAFE', 'Nontoxic Certified', 'third-party', 'ingredients', 'Screens every ingredient against a banned-substances list running to several thousand entries.'),
  ('cradle-to-cradle', 'Cradle to Cradle Certified', 'Cradle to Cradle Products Innovation Institute', 'third-party', 'materials and packaging', 'Assesses material health, water stewardship and packaging circularity. Says as much about the bottle as about what is in it.'),
  ('eu-ecolabel', 'EU Ecolabel', 'European Commission', 'third-party', 'lifecycle', 'Caps aquatic toxicity and requires biodegradability across the whole product lifecycle, verified by an accredited body.'),
  ('rspo', 'RSPO Certified', 'Roundtable on Sustainable Palm Oil', 'third-party', 'sourcing', 'Traces palm-derived surfactants to plantations meeting no-deforestation criteria. Chain-of-custody models vary in strength.'),
  ('leaping-bunny', 'Leaping Bunny', 'Cruelty Free International', 'third-party', 'animal welfare', 'No animal testing at any stage, verified by supply-chain audit. Unrelated to ingredient safety.'),
  ('b-corp', 'B Corp', 'B Lab', 'third-party', 'the company', 'Audits the business — governance, workers, environment. Says nothing whatsoever about what is in the bottle.'),
  ('clean-claim', '“Clean”', 'The brand itself', 'self-declared', 'nothing', 'No legal definition, no certifying body, no test to fail. Anyone may print it on anything.'),
  ('natural-claim', '“All natural”', 'The brand itself', 'self-declared', 'nothing', 'Unregulated outside of meat and poultry labeling. Carries no verifiable meaning on a cleaning product.'),
  ('plant-based-claim', '“Plant-based”', 'The brand itself', 'self-declared', 'nothing', 'Describes where a molecule started, not what it does. A harsh surfactant derived from coconut is still a harsh surfactant, and the claim survives if a single ingredient qualifies.'),
  ('nontoxic-claim', '“Non-toxic”', 'The brand itself', 'self-declared', 'nothing', 'Has a narrow legal meaning under federal hazard labeling and a much broader marketing one. On a front label it is the marketing meaning.'),
  ('eco-claim', '“Eco-friendly”', 'The brand itself', 'self-declared', 'nothing', 'The FTC’s Green Guides discourage unqualified environmental claims precisely because they cannot be substantiated. Widely used anyway.')
on conflict (id) do update set
    name = excluded.name,
    body = excluded.body,
    rigor = excluded.rigor,
    covers = excluded.covers,
    what = excluded.what;

