  ('tallgrass-stain', 'Enzyme Stain Remover', 'Tallgrass', 'laundry', 'stain remover', array['stain', 'spot', 'pre-treat', 'laundry', 'grass', 'wine', 'protein', 'fragrance-free']::text[], 10, '16 fl oz', array['enzymes', 'coco-glucoside', 'sodium-carbonate']::text[], array['safer-choice']::text[], '{}'::text[], 'pump-fern', 'Three ingredients aimed squarely at protein stains. Nothing added to make it smell like it worked.'),
  ('basin-dish', 'Dish Liquid No. 1, Unscented', 'Basin', 'dishwashing', 'dish liquid', array['dish', 'dishes', 'washing up', 'kitchen', 'sink', 'unscented', 'fragrance-free', 'hands']::text[], 7, '18 fl oz', array['coco-glucoside', 'glycerin', 'citric-acid', 'palm-oil']::text[], array['safer-choice', 'rspo']::text[], '{}'::text[], 'hand-pump-amber', 'Clear on health grounds, and honest about the palm derivatives — certified through a no-deforestation chain of custody rather than left unmentioned.'),
  ('lathermore-dish', 'Ultra Dish Soap, Green Apple', 'Lathermore', 'dishwashing', 'dish liquid', array['dish', 'dishes', 'washing up', 'kitchen', 'sink', 'scented', 'suds', 'foam']::text[], 4, '22 fl oz', array['sls', 'fragrance', 'limonene', 'palm-oil']::text[], '{}'::text[], array['natural-claim']::text[], 'bottle-citrus', 'The cheapest thing here per ounce, and the ingredient list explains why. Enormous suds, which is a marketing decision rather than a cleaning one.'),
  ('corvid-dishwasher', 'Dishwasher Tablets, Unscented', 'Corvid', 'dishwashing', 'dishwasher', array['dishwasher', 'tablets', 'tabs', 'machine', 'dishes', 'unscented', 'fragrance-free']::text[], 15, '60 tablets', array['sodium-carbonate', 'enzymes', 'citric-acid']::text[], array['safer-choice', 'eu-ecolabel']::text[], '{}'::text[], 'jar-tablets-gel', 'Enzymes and washing soda, no chlorine and no phosphates. Wrapper dissolves; there is no plastic film to peel.'),
  ('sunhill-dishwasher', 'Dishwasher Gel, Lavender', 'Sunhill', 'dishwashing', 'dishwasher', array['dishwasher', 'gel', 'liquid', 'machine', 'dishes', 'scented', 'lavender']::text[], 6, '75 fl oz', array['sodium-hypochlorite', 'phosphates', 'fragrance', 'edta']::text[], '{}'::text[], array['eco-claim']::text[], 'bottle-lavender-basket', 'Chlorine for the tea stains, phosphates for hard water, and an eco-friendly claim doing a great deal of unsupported work on the front label.'),
  ('marrow-moss-handsoap', 'Hand Soap, Bare', 'Marrow & Moss', 'hands', 'hand soap', array['hand soap', 'hands', 'sink', 'washing', 'fragrance-free', 'unscented', 'sensitive', 'dry skin']::text[], 12, '12 fl oz', array['coco-glucoside', 'glycerin', 'citric-acid', 'phenoxyethanol']::text[], array['ewg-verified', 'b-corp']::text[], '{}'::text[], 'hand-lemons-moss', 'Four ingredients, one of them a preservative at the standard limit. Glycerin is why twenty washes a day does not leave your hands cracked.'),
  ('ledger-handsoap', 'Foaming Hand Soap, Cedar', 'Ledger', 'hands', 'hand soap', array['hand soap', 'hands', 'foaming', 'sink', 'washing', 'scented', 'antibacterial']::text[], 6, '10 fl oz', array['sles', 'fragrance', 'methylparaben', 'triclosan', 'linalool']::text[], '{}'::text[], array['nontoxic-claim']::text[], 'foaming-pump-lemon', 'Carries an antibacterial the FDA removed from consumer hand soap in 2016, after manufacturers could not show it beat plain soap and water.')
